//! gshapes: the generic-operator engine of spikes/generic-ops (its source files, included with #[path]: its Q1
//! group-by and Q6 filtered sum) on lineitem-shaped data sets with many NULLs, generated by `gcp-check.sh`.
//!
//!   gshapes list [tag]                      name, data-set tag, expected outcome (`ok` or `refuse`)
//!   gshapes sql <name>                      the DuckDB SQL
//!   gshapes run <dir> <name> <threads> <out>
//!
//! Result text: the engine's own CSV with ',' turned into '|' (the harness compares with DuckDB's list output,
//! sorted bytewise). Exit status: 0 ok, 3 refused with "not supported yet" (the generic Q1 sink refuses a NULL
//! group key; a data set that must be refused is marked `refuse` in `list`), 4 other engine error, 101 panic.
//! Not applicable here, by design of that engine: Q1 supports at most 32 distinct key values and dictionary keys,
//! so the skewed-key and string-heavy sets (millions of keys) cannot be run through it.
#![allow(dead_code)]
#[path = "../../../generic-ops/src/engine.rs"]
mod engine;
#[path = "../../../generic-ops/src/kernels.rs"]
mod kernels;
#[path = "../../../generic-ops/src/source.rs"]
mod source;

use std::time::Instant;

use arrow::array::RecordBatch;
use engine::{Plan, q1, q6, run};
use source::Source;

#[path = "../gtable.rs"]
mod gtable;
use gtable::{queries, sql};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let all = queries();
    let find = |name: &str| all.iter().find(|q| q.name == name).unwrap_or_else(|| panic!("unknown query {name}"));
    match args.get(1).map(String::as_str) {
        Some("list") => {
            for q in all.iter().filter(|q| args.get(2).is_none_or(|t| *t == q.tag)) {
                println!("{}\t{}\t{}", q.name, q.tag, if q.refuse { "refuse" } else { "ok" });
            }
        }
        Some("sql") => println!("{}", sql(find(args.get(2).expect("query name")))),
        Some("run") => {
            let (dir, name) = (args.get(2).expect("dir"), args.get(3).expect("query"));
            let threads: usize = args.get(4).expect("threads").parse().expect("threads");
            let out_path = args.get(5).expect("outfile");
            let q = find(name);
            let plan: Plan = if q.q6 { q6() } else { q1() };
            let src = Source::open(&format!("{dir}/{}.parquet", q.table), plan.columns);
            let visit = |m: usize, f: &mut dyn FnMut(&RecordBatch)| {
                for rb in src.reader(m) {
                    f(&rb.expect("decode"));
                }
            };
            let t0 = Instant::now();
            let out = match run(src.row_groups, &visit, &plan, threads) {
                Ok(o) => o,
                Err(e) => {
                    println!("ENGINE-ERROR {}", e.0);
                    std::process::exit(if e.0.contains("not supported yet") { 3 } else { 4 });
                }
            };
            let engine_ms = t0.elapsed().as_secs_f64() * 1000.0;
            let mut text = out.csv().replace(',', "|");
            if !text.is_empty() {
                text.push('\n');
            }
            std::fs::write(out_path, &text).expect("write result");
            let rss = std::fs::read_to_string("/proc/self/status")
                .unwrap_or_default()
                .lines()
                .find_map(|l| l.strip_prefix("VmHWM:").and_then(|v| v.trim().strip_suffix("kB")).and_then(|v| v.trim().parse::<u64>().ok()))
                .unwrap_or(0);
            println!("engine_ms={engine_ms:.1} groups={} out_rows=0 rss_engine_kb={rss} rss_total_kb={rss}", text.lines().count());
        }
        _ => eprintln!("usage: gshapes list [tag] | sql <name> | run <dir> <name> <threads> <outfile>"),
    }
}
